import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import type { Pool } from "pg";
import { PrismaPg } from "@prisma/adapter-pg";
// Generated by `prisma generate` — see the comment in src/client.ts for why
// this can't be generated in the sandbox that authored this file.
import { PrismaClient } from "../src/generated/client/client.js";
import { seedCatalog } from "../src/seed.js";
import { createTestPool, truncateAll } from "./helpers/db.js";

/**
 * E2-04 (docs/08-execution-plan.md §5), US-21 AC2–AC3: the seed must be
 * idempotent and must produce the exact catalog shape 03-data-model.md §8
 * requires — one low-stock and one sold-out product, one bestseller per
 * category — and 06-development-workflow.md §5's "never resets stock" rule.
 *
 * Asserts via raw `pg` (not Prisma queries) so these checks stay valid even
 * if the generated client's shape changes; `seedCatalog` itself still needs
 * a real `PrismaClient` to call, since that's its signature (src/seed.ts).
 */
describe("E2-04 seed idempotency and shape (US-21 AC2-AC3)", () => {
  let pool: Pool;
  let prisma: PrismaClient;

  beforeAll(() => {
    pool = createTestPool();
    // createTestPool already validated DATABASE_URL points at a test db.
    prisma = new PrismaClient({
      adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL }),
    });
  });

  afterAll(async () => {
    await prisma.$disconnect();
    await pool.end();
  });

  beforeEach(async () => {
    await truncateAll(pool);
  });

  it("loads 3 categories, 1 tag, 6 products, one bestseller per category, and the required low-stock/sold-out products", async () => {
    await seedCatalog(prisma);

    const categories = await pool.query<{ slug: string }>("SELECT slug FROM categories");
    expect(categories.rows.map((r) => r.slug).sort()).toEqual(["chocolate", "classics", "fruity"]);

    const tags = await pool.query<{ slug: string }>("SELECT slug FROM tags");
    expect(tags.rows).toHaveLength(1);
    expect(tags.rows[0]!.slug).toBe("bestseller");

    const products = await pool.query<{ slug: string; stock_quantity: number }>(
      "SELECT slug, stock_quantity FROM products",
    );
    expect(products.rows).toHaveLength(6);

    const bestsellersPerCategory = await pool.query<{ category_slug: string; n: string }>(
      `SELECT c.slug AS category_slug, count(*) AS n
       FROM product_tags pt
       JOIN products p ON p.id = pt.product_id
       JOIN categories c ON c.id = p.category_id
       JOIN tags t ON t.id = pt.tag_id
       WHERE t.slug = 'bestseller'
       GROUP BY c.slug`,
    );
    expect(bestsellersPerCategory.rows).toHaveLength(3);
    for (const row of bestsellersPerCategory.rows) {
      expect(row.n).toBe("1");
    }

    const lowStock = products.rows.find((r) => r.slug === "cookies-and-cream");
    expect(lowStock?.stock_quantity).toBe(3);
    const soldOut = products.rows.find((r) => r.slug === "lemon-cream");
    expect(soldOut?.stock_quantity).toBe(0);
  });

  it("running the seed twice creates no duplicates", async () => {
    await seedCatalog(prisma);
    await seedCatalog(prisma);

    const counts = await pool.query<{ table_name: string; n: string }>(
      `SELECT 'categories' AS table_name, count(*) AS n FROM categories
       UNION ALL SELECT 'tags', count(*) FROM tags
       UNION ALL SELECT 'products', count(*) FROM products
       UNION ALL SELECT 'product_tags', count(*) FROM product_tags`,
    );
    const byTable = Object.fromEntries(counts.rows.map((r) => [r.table_name, Number(r.n)]));
    expect(byTable).toEqual({ categories: 3, tags: 1, products: 6, product_tags: 3 });
  });

  it("never resets stock that changed after the first seed (06-development-workflow.md §5)", async () => {
    await seedCatalog(prisma);
    await pool.query("UPDATE products SET stock_quantity = 7 WHERE slug = 'birthday-vanilla'");

    await seedCatalog(prisma);

    const { rows } = await pool.query<{ stock_quantity: number }>(
      "SELECT stock_quantity FROM products WHERE slug = 'birthday-vanilla'",
    );
    expect(rows[0]!.stock_quantity).toBe(7);
  });
});
